import continentSettings from "#base/scripts/voronoi_data/continents.mapconfig.js";
import { voronoiMapSchema } from "#base/scripts/voronoi_maps/map-common.js";
import {
	SectionSettings,
	UnifiedContinentsBase,
	UnifiedContinentsBaseSettings,
} from "#base/scripts/voronoi_maps/unified-continents-base.js";

export type VoronoiContinentsSettings = UnifiedContinentsBaseSettings;

export function buildContinentsSettings<T extends SectionSettings>(source: T): T {
	const result = { ...source };
	result.landmassCount = 2;
	result.distantCount = 0;
	result.landmassGroupCount = 2;
	result.minLandmassSpawnCenterDistance = 0.4;
	result.maxLandmassSpawnCenterDistance = 0.6;
	return result;
}

export class VoronoiContinents extends UnifiedContinentsBase<VoronoiContinentsSettings> {
	constructor() {
		super(voronoiMapSchema, continentSettings);
	}

	static getName(): string {
		return "Continents";
	}

	init(hexDims: float2) {
		// Continents drives these unified parameters programmatically; hide them from the UI.
		this.m_baseSchema.landmassCount.hidden = true;
		this.m_baseSchema.distantCount.hidden = true;
		this.m_baseSchema.landmassGroupCount.hidden = true;
		this.m_baseSchema.totalDistantSize.hidden = true;
		this.m_baseSchema.maxDistantSizeVariance.hidden = true;

		this.initInternal(hexDims);
	}

	override simulateInternal() {
		super.placeDefaultSection(buildContinentsSettings(this.m_settings));
	}

	getFilename(): string {
		return "continents.mapconfig.js";
	}
}
